use std::fs
use std::collections::HashMap

fn amt(s: string) -> int {
    s.parse::<int>().unwrap_or(0)
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut acc: HashMap<string, int> = HashMap::new()
    for line in text.lines() {
        let p: Vec<string> = line.split_whitespace().map(|x| x.to_string()).collect()
        let n: int = p.len() as int
        if n == 0 {
            continue
        }
        let cmd = p[0].clone()
        if cmd == "open" && n >= 3 {
            let a = amt(p[2].clone())
            if a < 0 {
                println("error: invalid amount")
            } else if acc.contains_key(p[1].as_str()) {
                println("error: duplicate account")
            } else {
                acc.insert(p[1].clone(), a)
                println("ok")
            }
        } else if cmd == "balance" && n >= 2 {
            if acc.contains_key(p[1].as_str()) {
                println("${acc[p[1].as_str()]}")
            } else {
                println("error: unknown account ${p[1]}")
            }
        } else if (cmd == "deposit" || cmd == "withdraw") && n >= 3 {
            let a = amt(p[2].clone())
            if a <= 0 {
                println("error: invalid amount")
            } else if !acc.contains_key(p[1].as_str()) {
                println("error: unknown account ${p[1]}")
            } else {
                let b = acc[p[1].as_str()]
                if cmd == "deposit" {
                    acc.insert(p[1].clone(), b + a)
                    println("ok")
                } else if b < a {
                    println("error: insufficient funds")
                } else {
                    acc.insert(p[1].clone(), b - a)
                    println("ok")
                }
            }
        } else if cmd == "transfer" && n >= 4 {
            let a = amt(p[3].clone())
            if a <= 0 {
                println("error: invalid amount")
            } else if !acc.contains_key(p[1].as_str()) {
                println("error: unknown account ${p[1]}")
            } else if !acc.contains_key(p[2].as_str()) {
                println("error: unknown account ${p[2]}")
            } else if p[1] == p[2] {
                println("error: same account")
            } else {
                let fb = acc[p[1].as_str()]
                let tb = acc[p[2].as_str()]
                if fb < a {
                    println("error: insufficient funds")
                } else {
                    acc.insert(p[1].clone(), fb - a)
                    acc.insert(p[2].clone(), tb + a)
                    println("ok")
                }
            }
        }
    }
    let mut keys: Vec<string> = acc.keys().map(|k| k.to_string()).collect()
    keys.sort()
    for k in keys {
        println("${k} ${acc[k.as_str()]}")
    }
}

